Langlands.IsobaricCuspData.mk.inj.type:
∀ {K : Type u} {inst : Field K} {inst_1 : NumberField K} {m card : ℕ} {size : Fin card → ℕ}
  {level : Fin card → NumberField.RingOfIntegers K} {form : (j : Fin card) → Langlands.AdelicGL K (size j) → ℂ}
  {isCuspForm : ∀ (j : Fin card), Langlands.IsCuspForm (level j) (form j)} {ne_zero : ∀ (j : Fin card), form j ≠ 0}
  {sum_size : ∑ j, size j = m} {card_1 : ℕ} {size_1 : Fin card_1 → ℕ}
  {level_1 : Fin card_1 → NumberField.RingOfIntegers K}
  {form_1 : (j : Fin card_1) → Langlands.AdelicGL K (size_1 j) → ℂ}
  {isCuspForm_1 : ∀ (j : Fin card_1), Langlands.IsCuspForm (level_1 j) (form_1 j)}
  {ne_zero_1 : ∀ (j : Fin card_1), form_1 j ≠ 0} {sum_size_1 : ∑ j, size_1 j = m},
  { card := card, size := size, level := level, form := form, isCuspForm := isCuspForm, ne_zero := ne_zero,
        sum_size := sum_size } =
      { card := card_1, size := size_1, level := level_1, form := form_1, isCuspForm := isCuspForm_1,
        ne_zero := ne_zero_1, sum_size := sum_size_1 } →
    card = card_1 ∧ size ≍ size_1 ∧ level ≍ level_1 ∧ form ≍ form_1

