Langlands.WeilDeligneRep.mk.inj.type:
∀ {K : Type u} {inst : Field K} {inst_1 : ValuativeRel K} {inst_2 : TopologicalSpace K}
  {inst_3 : IsNonarchimedeanLocalField K} {m : ℕ} {r : Langlands.WeilGroup K →* GL (Fin m) ℂ}
  {isOpen_ker : IsOpen ↑r.ker} {N : Matrix (Fin m) (Fin m) ℂ} {isNilpotent : IsNilpotent N}
  {conj : ∀ (w : Langlands.WeilGroup K), ↑(r w) * N * ↑(r w)⁻¹ = Langlands.weilNorm K w • N}
  {semisimple : ∀ (w : Langlands.WeilGroup K), Module.End.IsSemisimple (Matrix.toLin' ↑(r w))}
  {r_1 : Langlands.WeilGroup K →* GL (Fin m) ℂ} {isOpen_ker_1 : IsOpen ↑r_1.ker} {N_1 : Matrix (Fin m) (Fin m) ℂ}
  {isNilpotent_1 : IsNilpotent N_1}
  {conj_1 : ∀ (w : Langlands.WeilGroup K), ↑(r_1 w) * N_1 * ↑(r_1 w)⁻¹ = Langlands.weilNorm K w • N_1}
  {semisimple_1 : ∀ (w : Langlands.WeilGroup K), Module.End.IsSemisimple (Matrix.toLin' ↑(r_1 w))},
  { r := r, isOpen_ker := isOpen_ker, N := N, isNilpotent := isNilpotent, conj := conj, semisimple := semisimple } =
      { r := r_1, isOpen_ker := isOpen_ker_1, N := N_1, isNilpotent := isNilpotent_1, conj := conj_1,
        semisimple := semisimple_1 } →
